public async Task<CustomerUpdateOrderStatusResponse> Handle(UpdateCustomerOrderStatusCommand command, CancellationToken cancellationToken)
    {
        var order = await CustomerCheckoutSupport.LoadOwnedOrderAsync(dbContext, currentUser, command.OrderUuid, cancellationToken);
        order.StatusId = command.StatusId;
        order.Updated = DateTime.UtcNow;
        await dbContext.SaveChangesAsync(cancellationToken);

        string? eventLink = null;
        if (command.StatusId == 6 && order.TourTimeSlotsId.HasValue && order.TimeSlotDate.HasValue)
        {
            eventLink = $"{_options.PublicAppBaseUrl.TrimEnd('/')}/customer/images/{order.TourTimeSlotsId.Value}/{order.TimeSlotDate.Value:yyyy-MM-dd}";
        }

        return new CustomerUpdateOrderStatusResponse(
            true,
            order.Uuid,
            command.StatusId,
            eventLink,
            CustomerCheckoutSupport.ResolveHomepageLink(order.TourTimeSlot!.Tour!, _options),
            order.TourTimeSlot.Tour!.HomepageUrl,
            order.TourTimeSlot.Tour.ThemeColor,
            order.TourTimeSlot.Tour.DeliveryFee);
    }

