[HttpPost("{orderId}/updateStatus")]
    public Task<CustomerUpdateOrderStatusResponse> UpdateOrderStatus(string orderId, [FromBody] UpdateOrderStatusRequest request, CancellationToken cancellationToken)
    {
        return updateCustomerOrderStatusCommandHandler.Handle(new UpdateCustomerOrderStatusCommand(orderId, request.StatusId), cancellationToken);
    }

